test('create retries are durable across flag rollback, mismatched intent rejected, and admin inventory is shared', async () => {
    const body = make(); const [a, b] = await Promise.all([createAdminImport(actor.toHexString(), body), createAdminImport(actor.toHexString(), body)]); assert.equal(a.item.id, b.item.id);
    delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
    assert.equal((await createAdminImport(actor.toHexString(), body)).receipt!.revision, 1);
    await assert.rejects(create(), errorCode('ADMIN_IMPORTS_DISABLED'));
    await assert.rejects(createAdminImport(actor.toHexString(), { ...body, manifest: { ...body.manifest, rootLabel: 'different' } }), errorCode('ADMIN_IMPORT_OPERATION_CONFLICT'));
    assert.equal((await getAdminImport(other.toHexString(), a.item.id)).item.startedByMe, false);
    await assert.rejects(getAdminImport(ordinary.toHexString(), a.item.id), errorCode('ADMIN_IMPORT_ADMIN_REQUIRED'));
    assert.equal(await getDb()!.collection('adminAlbumImports').countDocuments(), 1);
});
test('concurrent saves of one path have one winner, saves of different paths both win, and replay survives later edits', async () => {
    const first = await create(), id = first.item.id, title = (value: string) => [{ path: 'album.title', base: '', value }];
    const requests = [{ by: actor, body: { ...mutation(1), changes: title('First') } }, { by: other, body: { ...mutation(1), changes: title('Other') } }];
    const results = await Promise.allSettled(requests.map(({ by, body }) => editAdminImport(by.toHexString(), id, body)));
    assert.equal(results.filter(r => r.status === 'fulfilled').length, 1);
    // The loser retries against the winner's value, which is another administrator's own: a stale path is refused.
    const lost = results.find(r => r.status === 'rejected') as PromiseRejectedResult; assert.equal(errorCode('ADMIN_IMPORT_FIELD_CONFLICT')(lost.reason), true);
    const current = await getAdminImport(actor.toHexString(), id); assert.equal(current.item.revision, 2);
    // Whichever request won, replaying it returns its receipt, before and after later saves.
    const winner = requests[results.findIndex(r => r.status === 'fulfilled')], replay = async () => (await editAdminImport(winner.by.toHexString(), id, winner.body)).receipt!.revision;
    assert.equal(current.item.draft.album.title, winner.body.changes[0].value); assert.equal(await replay(), 2);
    const slot = current.item.draft.tracks[0].slotId, date = { year: 2026, month: 5, day: null };
    await Promise.all([editAdminImport(actor.toHexString(), id, { ...mutation(2), changes: [{ path: 'album.releaseDate', base: null, value: date }] }),
        editAdminImport(other.toHexString(), id, { ...mutation(2), changes: [{ path: `tracks.${slot}.title`, base: '', value: 'Recording' }] })]);
    const both = await getAdminImport(actor.toHexString(), id);
    assert.deepEqual([both.item.revision, both.item.draft.album.releaseDate, both.item.draft.tracks[0].title, both.item.draft.album.title], [4, date, 'Recording', current.item.draft.album.title]);
    assert.equal(await replay(), 2); assert.equal((await getAdminImport(actor.toHexString(), id)).item.revision, 4);
});
