    if (results[0].status === 'fulfilled') assert.equal((await analyzeAdminImport(actor.toHexString(), a.item.id, body, provider)).item.analysis.generation, 1);
    const stored = await getDb()!.collection('adminAlbumImports').findOne({ _id: new ObjectId(winning.value.item.id) }); assert.equal(stored!.analysis.actorId, actor.toHexString()); assert.equal(stored!.analysis.chunks.length, 2); assert.equal(stored!.analysis.grantExpiresAt instanceof Date, true);
