test('a project saved in a newer draft format is read-only: edits, analysis, adoption, decisions, publication and cover selection are refused unchanged', async () => {
    const { id, item } = await newerProject(), before = await stored(id), by = a1.toHexString(), revision = item.revision;
    let calls = 0; const counted: ImportAnalysisProvider = { configured: () => true, analyze: async input => { calls++; return provider.analyze(input); } };
    for (const work of [
        () => editAdminImport(by, id, { ...mutation(revision), draft: item.draft }),
        () => analyzeAdminImport(by, id, mutation(revision), counted),
        () => adoptAdminImportSuggestions(by, id, { ...mutation(revision), generation: 1, selectedIds: [item.suggestions[0].id], rejectIds: [] }),
        () => decideAdminImportDuplicates(by, id, { ...mutation(revision), decisions: item.decisions }),
        () => publishAdminImport(by, id, mutation(revision)),
        // A one-step approval of what the editor showed is refused the same way.
        () => publishAdminImport(by, id, approvalBody(item)),
        () => selectAdminImportCover(by, id, { ...mutation(revision), slotId: null })
    ]) await assert.rejects(work(), errorCode('ADMIN_IMPORT_RELOAD_REQUIRED'));
    // Refusals precede any change: no receipt, revision, draft or analysis is written.
    assert.deepEqual(await stored(id), before);
    // A stored receipt still replays its original response.
    const edit = before!.receipts.find(receipt => receipt.kind === 'edit')!;
    const replay = await editAdminImport(by, id, { operationId: edit.operationId, expectedRevision: edit.revision - 1, draft: legacyDraftView(before!.draft, before!.manifest) });
    assert.deepEqual(replay.receipt, { operationId: edit.operationId, kind: 'edit', revision: edit.revision }); assert.deepEqual(await stored(id), before);
    // Its queued analysis is never claimed, so no provider call and no checkpoint happen.
    assert.equal(await runAdminImportWorkerOnce(counted), false); assert.equal(calls, 0); assert.deepEqual(await stored(id), before);
    // Stopping work stays admitted and keeps the newer format.
    const cancelled = await cancelAdminImportAnalysis(a2.toHexString(), id, mutation(revision));
    assert.equal(cancelled.item.analysis.state, 'cancelled'); assert.equal(cancelled.receipt!.kind, 'cancel-analysis'); assert.equal(cancelled.item.revision, revision + 1);
    const after = await stored(id); assert.equal(after!.draftVersion, 3); assert.deepEqual(after!.draft, before!.draft); assert.deepEqual(after!.draftOrigins, before!.draftOrigins);
    assert.equal(after!.receipts.at(-1)!.kind, 'cancel-analysis'); assert.equal(calls, 0);
});
test('reads of a newer-format project expose only the Draft v2 allowlist in detail and the v1 allowlist in inventory and duplicate candidates', async () => {
    const { id } = await newerProject(), artistId = new ObjectId();
    const detail = await getAdminImport(a2.toHexString(), id), page = await listAdminImports(a2.toHexString(), {});
    // The editor DTO names each decision's entry and bound name (none for a newer format); the inventory keeps the v1 allowlist.
    const v1Only = ['musicBrainzId', 'discNumber', 'Synthetic Label', 'joinPhrase', 'entryKey', 'boundName', 'identifiers', 'albumArtists', 'automaticPaths', 'valueRevision'];
    for (const sentinel of ['futureAlbumField', 'draftOrigins', 'draftVersion', 'albumArtist"', '0000000000f2', 'lookup-', 'futureTopLevel', 'automatedAt', ...v1Only]) {
        assert.equal(JSON.stringify(page).includes(sentinel), false, sentinel);
        if (!v1Only.includes(sentinel)) assert.equal(JSON.stringify(detail).includes(sentinel), false, sentinel);
    }
    // A newer format binds no name and marks nothing automatic, and its version-less evidence reads as version 1 (the album
    // artist and release ID it stores are never shown).
    assert.ok(detail.item.decisions.every(decision => decision.entryKey === null && decision.boundName === null));
    assert.deepEqual([detail.item.automaticPaths, detail.item.possibleLabelEntryKeys, detail.item.valueRevision], [[], [], 0]);
    assert.ok(detail.item.assets.some(asset => asset.tags !== null) && detail.item.assets.every(asset => asset.tags === null || (asset.tags.version === 1 && asset.tags.albumArtists.length === 0 && asset.tags.identifiers.musicBrainzReleaseId === null)));
    assert.equal(detail.item.startedByMe, false); assert.deepEqual(detail.item.draft.album.artists.map(entry => entry.name), ['Synthetic Primary', 'Synthetic Guest']);
    assert.deepEqual(detail.item.capabilities, { analysis: false, upload: false, publish: false });
    assert.equal(page.items.length, 1);
    assert.deepEqual([page.items[0].title, page.items[0].artistName, page.items[0].visibility, page.items[0].rootLabel], ['Synthetic Compat Album', 'Synthetic Primary', 'public', 'Synthetic Primary - Synthetic Compat Album']);
    // The inventory counts the pending suggestions the detail shows, not stored ones a v1 client cannot read.
    assert.equal(page.items[0].pendingSuggestions, 2); assert.deepEqual(detail.item.suggestions.filter(suggestion => suggestion.decision === 'pending').map(suggestion => suggestion.field), ['artists', 'title']);
    // Candidates read the Draft v2 view (each entry name, then the label), so the primary entry still finds its existing Artist.
    await getDb()!.collection('artists').insertOne({ _id: artistId, name: 'Synthetic Primary', lifecycleStatus: 'ready', visibility: 'public' });
    const { items } = await adminImportDuplicateCandidates(a1.toHexString(), id);
    assert.deepEqual(items.filter(candidate => candidate.kind === 'artist').map(candidate => [candidate.id, candidate.label]), [[artistId.toHexString(), 'Synthetic Primary']]);
});
test('newer-format analyses, queued or with a chunk left in flight, hold no analysis capacity and are never claimed', async () => {
    const { id: queuedId } = await newerProject(), imports = getDb()!.collection<AdminImportDocument>('adminAlbumImports');
    // A newer release's worker died mid-call: its project is running with an expired lease and a chunk in flight.
    const inflight = newerFixture(); inflight._id = new ObjectId(); inflight.manifest.rootLabel = 'Synthetic in-flight project';
    Object.assign(inflight.analysis, { state: 'running', leaseOwner: randomUUID(), leaseUntil: new Date(Date.now() - 60_000) });
    Object.assign(inflight.analysis.chunks[1], { state: 'inflight', attemptId: randomUUID(), startedAt: new Date(Date.now() - 120_000) });
    await imports.insertOne(inflight); const inflightId = inflight._id.toHexString();
    // Both sort before any new project, so a worker that could claim them would.
    await imports.updateMany({ draftVersion: 3 }, { $set: { createdAt: new Date(0) } });
    let calls = 0; const counted: ImportAnalysisProvider = { configured: () => true, analyze: async input => { calls++; assert.notEqual(input.manifest.rootLabel, inflight.manifest.rootLabel); return provider.analyze(input); } };
    // The initiator of both newer analyses may start one here, and so may a second administrator.
    const first = await createAdminImport(a1.toHexString(), make());
    assert.equal((await analyzeAdminImport(a1.toHexString(), first.item.id, mutation(1), counted)).item.analysis.state, 'queued');
    const stopped = await cancelAdminImportAnalysis(a2.toHexString(), inflightId, mutation(inflight.revision));
    assert.equal(stopped.item.analysis.state, 'cancelled');
    const second = await createAdminImport(a2.toHexString(), make());
    assert.equal((await analyzeAdminImport(a2.toHexString(), second.item.id, mutation(1), counted)).item.analysis.state, 'queued');
    // The global limit still binds the projects this release dispatches.
    const third = await create(); await assert.rejects(analyzeAdminImport(actor.toHexString(), third.item.id, mutation(1), counted), errorCode('ADMIN_IMPORT_CAPACITY'));
    const before = await imports.find({ draftVersion: 3 }).sort({ _id: 1 }).toArray();
    for (let tick = 0; tick < 8 && await runAdminImportWorkerOnce(counted); tick++);
    assert.equal(await runAdminImportWorkerOnce(counted), false); assert.equal(calls, 4);
    for (const id of [first.item.id, second.item.id]) assert.equal((await getAdminImport(a1.toHexString(), id)).item.analysis.state, 'complete');
    // Neither newer project was claimed, settled or rewritten; the in-flight chunk is left for a release that knows the format.
    assert.deepEqual(await imports.find({ draftVersion: 3 }).sort({ _id: 1 }).toArray(), before);
    const held = await stored(inflightId), queued = await stored(queuedId);
    assert.deepEqual([held!.analysis.state, held!.analysis.chunks.map(chunk => chunk.state)], ['cancelled', ['complete', 'inflight']]);
    assert.deepEqual([queued!.analysis.state, queued!.analysis.chunks.map(chunk => chunk.state)], ['queued', ['complete', 'pending']]);
});
test('an analysis claimed just before a newer release saved its project is released without a provider call or checkpoint', async () => {
    const first = await create(), _id = new ObjectId(first.item.id); await analyzeAdminImport(actor.toHexString(), first.item.id, mutation(1), provider);
    const queued = await stored(first.item.id), db = getDb()!, original = db.collection.bind(db);
    // The newer release saves the project between this worker's claim and its transaction.
    (db as any).collection = (name: string, ...args: any[]) => {
        const target = original(name, ...args); if (name !== 'adminAlbumImports') return target;
        return new Proxy(target, { get(value, property) {
            if (property === 'findOneAndUpdate') return async (...call: any[]) => { const claimed = await (value as any).findOneAndUpdate(...call); await value.updateOne({ _id }, { $set: { draftVersion: 3 } }); return claimed; };
            const member = (value as any)[property]; return typeof member === 'function' ? member.bind(value) : member;
        } });
    };
    let calls = 0;
    try { await runAdminImportWorkerOnce({ configured: () => true, analyze: async () => { calls++; return []; } }); } finally { (db as any).collection = original; }
    const after = await stored(first.item.id);
    assert.equal(calls, 0); assert.deepEqual([after!.analysis.state, after!.analysis.leaseOwner, after!.analysis.leaseUntil, after!.attemptsUsed], ['queued', null, null, 0]);
    assert.deepEqual(after!.analysis.chunks, queued!.analysis.chunks); assert.equal(after!.revision, queued!.revision); assert.deepEqual(after!.suggestions, []);
});

