test('a legacy project converts at its first admitted change without starting analysis, and its pending Artist suggestion can be accepted, rejected or conflict', async () => {
    const { id: editedId, doc } = await legacyProject('v1-analysis-pending-artist-name.json'), by = a1.toHexString();
    const opened = await getAdminImport(by, editedId), suggestion = opened.item.suggestions.find(value => value.field === 'artists')!;
    assert.deepEqual([suggestion.baseline, (suggestion.value as { name: string }[]).map(value => value.name), suggestion.decision], [[], ['Synthetic Artist'], 'pending']);
    const edited = await editImportDraft(by, editedId, opened.item, draft => { draft.album.title = 'Converted title'; });
    const converted = await stored(editedId);
    assert.deepEqual([converted!.draftVersion, converted!.draft.album, converted!.analysis.state, converted!.analysis.chunks, converted!.attemptsUsed, converted!.analysis.generation],
        [2, { title: 'Converted title', artists: [], label: null, releaseDate: null, visibility: 'hidden' }, doc.analysis.state, doc.analysis.chunks, doc.attemptsUsed, doc.analysis.generation]);
    assert.equal(converted!.draftOrigins!['album:artists'], 'administrator'); assert.equal(converted!.receipts.length, doc.receipts.length + 1);
    // The converted pending suggestion is accepted against its converted baseline; acceptance makes the entries the administrator's own.
    const accepted = await adoptAdminImportSuggestions(by, editedId, { ...mutation(edited.item.revision), generation: 1, selectedIds: [suggestion.id], rejectIds: [] });
    assert.deepEqual([accepted.item.draft.album.artists.map(value => [value.key, value.name, value.role]), accepted.item.suggestions.find(value => value.id === suggestion.id)!.decision],
        [[[legacyArtistEntryKey(editedId), 'Synthetic Artist', 'primary']], 'accepted']);
    // Rejecting it directly converts the project with that change.
    const { id: rejectedId } = await legacyProject('v1-analysis-pending-artist-name.json');
    const rejected = await adoptAdminImportSuggestions(by, rejectedId, { ...mutation(doc.revision), generation: 1, selectedIds: [], rejectIds: [suggestion.id] });
    assert.deepEqual([rejected.item.draft.album.artists, (await stored(rejectedId))!.draftVersion], [[], 2]);
    // After the entries changed, accepting it reports a conflict instead of replacing them.
    const { id: conflictId } = await legacyProject('v1-analysis-pending-artist-name.json'), current = await getAdminImport(by, conflictId);
    const typed = await editImportDraft(by, conflictId, current.item, draft => { draft.album.artists = artistEntries('Typed Artist'); });
    await assert.rejects(adoptAdminImportSuggestions(by, conflictId, { ...mutation(typed.item.revision), generation: 1, selectedIds: [suggestion.id], rejectIds: [] }), errorCode('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.deepEqual((await getAdminImport(by, conflictId)).item.draft.album.artists.map(value => value.name), ['Typed Artist']);
});

