const projects = () => getDb()!.collection<AdminImportDocument>('adminAlbumImports');
/** Replaces a stored project whole, as automation or another release would write it; origin keys contain dots, so never `$set` them. */
async function rewrite(id: string, change: (doc: AdminImportDocument) => void) { const doc = (await stored(id))!; change(doc); await projects().replaceOne({ _id: doc._id }, doc); return doc; }
const v2 = (doc: AdminImportDocument | null) => doc!.draft as ImportDraftV2;

test('a refused change leaves a legacy project unconverted, and stopping work or replaying it never converts the project', async () => {
    const { id, doc } = await legacyProject('v1-analysis-pending-artist-name.json'), by = a1.toHexString(), before = await stored(id), slot = doc.manifest.files[0].slotId;
    // Every legacy value is the administrator's own, so a stale base conflicts; an invalid value or an unknown suggestion is refused.
    await assert.rejects(editAdminImport(by, id, { ...mutation(doc.revision), changes: [{ path: 'album.title', base: 'Not the saved title', value: 'Mine' }] }), errorCode('ADMIN_IMPORT_FIELD_CONFLICT'));
    await assert.rejects(editAdminImport(by, id, { ...mutation(doc.revision), changes: [{ path: `tracks.${slot}.discNumber`, base: null, value: 0 }] }), errorCode('ADMIN_IMPORT_INVALID_INPUT'));
    await assert.rejects(adoptAdminImportSuggestions(by, id, { ...mutation(doc.revision), generation: 1, selectedIds: ['f'.repeat(24)], rejectIds: [] }), errorCode('ADMIN_IMPORT_SUGGESTION_STALE'));
    assert.deepEqual(await stored(id), before);
    // Stopping work is recorded on the v1 document as it is; its replay changes nothing.
    const stopped = await cancelAdminImportAnalysis(a2.toHexString(), id, mutation(doc.revision)), afterStop = await stored(id);
    assert.deepEqual([stopped.receipt!.kind, afterStop!.revision, 'draftVersion' in afterStop!, 'draftOrigins' in afterStop!], ['cancel-analysis', doc.revision + 1, false, false]);
    assert.deepEqual([afterStop!.draft, afterStop!.suggestions, afterStop!.decisions, afterStop!.analysis.baseline], [before!.draft, before!.suggestions, before!.decisions, before!.analysis.baseline]);
    const replay = await cancelAdminImportAnalysis(a2.toHexString(), id, { operationId: stopped.receipt!.operationId, expectedRevision: doc.revision });
    assert.deepEqual(replay.receipt, stopped.receipt); assert.deepEqual(await stored(id), afterStop);
    // Reads still show the Draft v2 view of the unconverted project.
    assert.deepEqual([replay.item.draft.album.artists, replay.item.draft.tracks.map(track => track.discNumber)], [[], doc.manifest.files.map(() => null)]);
});

test('an administrator save replaces an automatic value but not another administrator\'s, and refused saves keep entries, the label and Disc Numbers', async () => {
    const created = await create(), id = created.item.id;
    const full = await editImportDraft(actor.toHexString(), id, created.item, draft => {
        draft.album.artists = [entry('Lorem', 'primary', ' & '), entry('Ipsum', 'featured')]; draft.album.label = { name: 'Synthetic Label', musicBrainzId: null }; draft.tracks[0].discNumber = 2;
    });
    // Automation (S8) filled the Album title after this editor opened.
    await rewrite(id, doc => { v2(doc).album.title = 'Tagged title'; doc.draftOrigins!['album:title'] = 'automatic'; });
    const mine = await editAdminImport(other.toHexString(), id, { ...mutation(full.item.revision), changes: [{ path: 'album.title', base: '', value: 'Mine' }] });
    assert.equal(mine.item.draft.album.title, 'Mine'); assert.equal((await stored(id))!.draftOrigins!['album:title'], 'administrator');
    // An editor that opened before both saves is now stale on another administrator's value.
    await assert.rejects(editAdminImport(actor.toHexString(), id, { ...mutation(full.item.revision), changes: [{ path: 'album.title', base: '', value: 'Theirs' }] }), errorCode('ADMIN_IMPORT_FIELD_CONFLICT'));
    const saved = await stored(id);
    await assert.rejects(editAdminImport(actor.toHexString(), id, { ...mutation(mine.item.revision), draft: legacyDraftView(saved!.draft, saved!.manifest) }), errorCode('ADMIN_IMPORT_RELOAD_REQUIRED'));
    await getDb()!.collection('users').updateOne({ _id: other }, { $set: { role: 'user' } });
    await assert.rejects(editAdminImport(other.toHexString(), id, { ...mutation(mine.item.revision), changes: [{ path: 'album.title', base: 'Mine', value: 'After role loss' }] }), errorCode('ADMIN_IMPORT_ADMIN_REQUIRED'));
    const after = await stored(id); assert.deepEqual(after, saved);
    assert.deepEqual([v2(after).album.artists.map(value => [value.name, value.role, value.joinPhrase]), v2(after).album.label, v2(after).tracks[0].discNumber],
        [[['Lorem', 'primary', ' & '], ['Ipsum', 'featured', null]], { name: 'Synthetic Label', musicBrainzId: null }, 2]);
});

test('the 48 KB draft cap refuses a growing save without a write, while a converted legacy draft over the cap stays editable', async () => {
    const files = Array.from({ length: 100 }, (_, index) => ({ slotId: randomUUID(), filename: `${index}.mp3`, relativePath: `${index}.mp3`, byteLength: 1 }));
    const created = await createAdminImport(actor.toHexString(), { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Large', files } }), id = created.item.id;
    const long = '漢'.repeat(300), titles = (count: number) => files.slice(0, count).map(file => ({ path: `tracks.${file.slotId}.title`, base: '', value: long }));
    const empty = await stored(id);
    await assert.rejects(editAdminImport(actor.toHexString(), id, { ...mutation(1), changes: titles(60) }), errorCode('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await stored(id), empty);
    const within = await editAdminImport(actor.toHexString(), id, { ...mutation(1), changes: titles(40) });
    assert.ok(draftBytes((await stored(id))!.draft) <= 48_000); assert.equal(within.item.draft.tracks[39].title, long);
    // A v1 draft within the cap grows past it when converted (Disc Numbers, entries and label are added).
    const title = '漢'.repeat(132), now = new Date(), legacy: AdminImportDocument = {
        _id: new ObjectId(), actorId: actor.toHexString(), revision: 1, createdAt: now, updatedAt: now, manifest: { rootLabel: 'Synthetic Large', files },
        draft: { album: { title: 'Synthetic Large', artistName: 'Lorem', releaseDate: null, visibility: 'hidden' }, tracks: files.map(file => ({ slotId: file.slotId, title, trackNumber: null })) },
        analysis: idleAnalysis(), analysisHistory: [], attemptsUsed: 0, suggestions: [], decisions: [], receipts: [{ operationId: randomUUID(), kind: 'create', revision: 1, hash: '0'.repeat(64), actorId: actor.toHexString(), at: now }]
    };
    await projects().insertOne(legacy); const legacyId = legacy._id.toHexString(), unconverted = await stored(legacyId);
    assert.ok(draftBytes(legacy.draft) <= 48_000); assert.ok(draftBytes(importDraftV2FromV1(legacy.draft as Parameters<typeof importDraftV2FromV1>[0], legacyId)) > 48_000);
    // A growing first change is refused, and its conversion with it.
    await assert.rejects(editAdminImport(actor.toHexString(), legacyId, { ...mutation(1), changes: [{ path: 'album.title', base: 'Synthetic Large', value: 'Synthetic Larger' }] }), errorCode('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await stored(legacyId), unconverted);
    // Changes that do not grow the converted draft are admitted, so the project stays editable.
    await editAdminImport(actor.toHexString(), legacyId, { ...mutation(1), changes: [{ path: `tracks.${files[0].slotId}.title`, base: title, value: 'Short' }] });
    await editAdminImport(actor.toHexString(), legacyId, { ...mutation(2), changes: [{ path: 'album.visibility', base: 'hidden', value: 'public' }] });
    const converted = await stored(legacyId);
    assert.deepEqual([converted!.draftVersion, converted!.revision, v2(converted).tracks[0].title, v2(converted).album.visibility], [2, 3, 'Short', 'public']); assert.ok(draftBytes(converted!.draft) > 48_000);
    await assert.rejects(editAdminImport(actor.toHexString(), legacyId, { ...mutation(3), changes: [{ path: 'album.title', base: 'Synthetic Large', value: 'Synthetic Larger' }] }), errorCode('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await stored(legacyId), converted);
});

test('a malformed stored Draft v2 asks for a reload and writes nothing, while reads still show the allowlisted draft', async () => {
    const created = await create(), id = created.item.id, slot = created.item.manifest.files[0].slotId;
    await rewrite(id, doc => { v2(doc).tracks = []; });
    const missingTrack = await stored(id);
    await assert.rejects(editAdminImport(actor.toHexString(), id, { ...mutation(1), changes: [{ path: `tracks.${slot}.title`, base: '', value: 'Lost' }] }), errorCode('ADMIN_IMPORT_RELOAD_REQUIRED'));
    assert.deepEqual(await stored(id), missingTrack);
    await rewrite(id, doc => { (v2(doc).album as unknown as Record<string, unknown>).artists = 'not entries'; });
    const malformed = await stored(id);
    for (const work of [
        () => editAdminImport(actor.toHexString(), id, { ...mutation(1), changes: [{ path: 'album.title', base: '', value: 'Lost' }] }),
        () => decideAdminImportDuplicates(actor.toHexString(), id, { ...mutation(1), decisions: [] })
    ]) await assert.rejects(work(), errorCode('ADMIN_IMPORT_RELOAD_REQUIRED'));
    assert.deepEqual(await stored(id), malformed);
    const read = await getAdminImport(actor.toHexString(), id);
    assert.deepEqual([read.item.draft.album.artists, read.item.draft.tracks], [[], [{ slotId: slot, title: '', discNumber: null, trackNumber: null }]]);
});

const lunaArtist: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [
    { scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: 'Suggested Album', source: 'folder', evidence: 'folder' },
    { scope: 'album', slotId: null, field: 'artistName', baseline: input.baseline.album.artistName, value: 'Ipsum Quartet', source: 'folder', evidence: 'folder' }] : [] };
const settle = async (luna: ImportAnalysisProvider) => { for (let tick = 0; tick < 6 && await runAdminImportWorkerOnce(luna); tick++); };

test('accepting suggestions makes their values the administrator\'s own and clears an Artist decision whose entry they rename', async () => {
    const first = await create(), id = first.item.id, named = await editImportDraft(actor.toHexString(), id, first.item, draft => { draft.album.artists = artistEntries('Lorem Ensemble'); }), key = named.item.draft.album.artists[0].key;
    const artist = { scope: 'artist', slotId: null, entryKey: key, boundName: 'Lorem Ensemble', action: 'create-distinct', candidateId: null, candidateRevision: null }, album = { ...artist, scope: 'album', entryKey: null, boundName: null };
    const decided = await decideAdminImportDuplicates(actor.toHexString(), id, { ...mutation(named.item.revision), decisions: [artist, album] });
    await analyzeAdminImport(actor.toHexString(), id, mutation(decided.item.revision), lunaArtist); await settle(lunaArtist);
    // Automation (S8) owns the Album title by the time the administrator accepts the suggestions.
    await rewrite(id, doc => { doc.draftOrigins!['album:title'] = 'automatic'; });
    const done = await getAdminImport(actor.toHexString(), id);
    assert.deepEqual([done.item.suggestions.map(suggestion => suggestion.field), done.item.decisions], [['title', 'artists'], [artist, album]]);
    const adopted = await adoptAdminImportSuggestions(actor.toHexString(), id, { ...mutation(done.item.revision), generation: 1, selectedIds: done.item.suggestions.map(suggestion => suggestion.id), rejectIds: [] });
    const doc = await stored(id);
    assert.deepEqual([adopted.item.draft.album.title, adopted.item.draft.album.artists.map(value => [value.key, value.name, value.role])], ['Suggested Album', [[key, 'Ipsum Quartet', 'primary']]]);
    assert.deepEqual([doc!.draftOrigins!['album:title'], doc!.draftOrigins!['album:artists']], ['administrator', 'administrator']);
    // The renamed entry is not the one its Artist decision was made for, so that decision is reviewed again.
    assert.deepEqual([adopted.item.decisions, doc!.decisions.map(decision => decision.scope)], [[album], ['album']]);
});

test('an analysis queued before Draft v2 completes on its v1 project, and its Artist-name suggestion is accepted as one primary entry', async () => {
    const first = await create(), id = first.item.id; await analyzeAdminImport(actor.toHexString(), id, mutation(1), lunaArtist);
    // The document an earlier release stored: a v1 draft and baseline, and no format markers.
    await rewrite(id, doc => { const legacy = legacyDraftView(doc.draft, doc.manifest); doc.draft = legacy; doc.analysis.baseline = structuredClone(legacy); delete doc.draftVersion; delete doc.draftOrigins; });
    await settle(lunaArtist);
    const finished = await stored(id);
    assert.deepEqual(['draftVersion' in finished!, finished!.analysis.state, finished!.suggestions.map(value => [value.field, value.baseline, value.value])], [false, 'complete', [['title', '', 'Suggested Album'], ['artistName', '', 'Ipsum Quartet']]]);
    const read = await getAdminImport(actor.toHexString(), id), suggestion = read.item.suggestions.find(value => value.field === 'artists')!, entryValue = { key: legacyArtistEntryKey(id), name: 'Ipsum Quartet', role: 'primary', joinPhrase: null, musicBrainzId: null };
    assert.deepEqual([suggestion.baseline, suggestion.value], [[], [entryValue]]);
    const accepted = await adoptAdminImportSuggestions(actor.toHexString(), id, { ...mutation(read.item.revision), generation: 1, selectedIds: [suggestion.id], rejectIds: [] }), converted = await stored(id);
    assert.deepEqual([converted!.draftVersion, v2(converted).album.artists, accepted.item.draft.album.artists, converted!.draftOrigins!['album:artists']], [2, [entryValue], [entryValue], 'administrator']);
    assert.deepEqual(converted!.suggestions.map(value => [value.field, value.decision]), [['title', 'pending'], ['artists', 'accepted']]);
});

/** Pads a stored project's ordinary receipts up to the limit, as 255 earlier admitted changes would. */
const exhaust = (doc: AdminImportDocument) => { while (doc.receipts.length < ADMIN_IMPORT_LIMITS.receipts) doc.receipts.push({ operationId: randomUUID(), kind: 'edit', revision: doc.revision, actorId: doc.actorId, hash: '0'.repeat(64), at: new Date() }); };
test('at the receipt limit a field save is refused and an outdated whole-draft save asks for a reload, without a write or conversion, while an earlier save still replays', async () => {
    const created = await create(), id = created.item.id, body = { ...mutation(1), changes: [{ path: 'album.title', base: '', value: 'Saved before the limit' }] };
    const saved = await editAdminImport(actor.toHexString(), id, body); await rewrite(id, exhaust);
    const full = await stored(id);
    // An editor that predates Draft v2 always gets its reload request, before the limit is checked.
    await assert.rejects(editAdminImport(actor.toHexString(), id, { ...mutation(saved.item.revision), changes: [{ path: 'album.title', base: 'Saved before the limit', value: 'Over the limit' }] }), errorCode('ADMIN_IMPORT_OPERATION_LIMIT'));
    await assert.rejects(editAdminImport(actor.toHexString(), id, { ...mutation(saved.item.revision), draft: legacyDraftView(full!.draft, full!.manifest) }), errorCode('ADMIN_IMPORT_RELOAD_REQUIRED'));
    assert.deepEqual(await stored(id), full);
    assert.deepEqual((await editAdminImport(actor.toHexString(), id, body)).receipt, saved.receipt); assert.deepEqual(await stored(id), full);
    const { id: legacyId, doc } = await legacyProject('v1-draft.json', exhaust), legacyBefore = await stored(legacyId);
    await assert.rejects(editAdminImport(a1.toHexString(), legacyId, { ...mutation(doc.revision), changes: [{ path: 'album.title', base: 'Synthetic Album', value: 'Over the limit' }] }), errorCode('ADMIN_IMPORT_OPERATION_LIMIT'));
    assert.deepEqual(await stored(legacyId), legacyBefore); assert.equal('draftVersion' in legacyBefore!, false);
});

test('a legacy value over its bound after NFC reads as empty, and a save from that shown value converts the project and replaces it', async () => {
    // U+0958 stores as two code units after NFC, and the frozen v1 parser bounded text before NFC, so these values were accepted.
    const nukta = String.fromCodePoint(0x958), long = (count: number) => nukta.repeat(count).normalize('NFC');
    const { id, doc } = await legacyProject('v1-draft.json', value => { const legacy = value.draft as ImportDraft; legacy.album.artistName = long(150); legacy.tracks[0].title = long(200); });
    const by = a1.toHexString(), opened = await getAdminImport(by, id), slot = (doc.draft as ImportDraft).tracks[0].slotId, before = await stored(id);
    assert.deepEqual([long(150).length, opened.item.draft.album.artists, opened.item.draft.tracks.find(track => track.slotId === slot)!.title], [300, [], '']);
    // Any other base is still stale, and the refused save leaves the project unconverted.
    await assert.rejects(editAdminImport(by, id, { ...mutation(doc.revision), changes: [{ path: `tracks.${slot}.title`, base: 'Not shown', value: 'Short title' }] }), errorCode('ADMIN_IMPORT_FIELD_CONFLICT'));
    assert.deepEqual(await stored(id), before);
    const saved = await editImportDraft(by, id, opened.item, draft => { draft.album.artists = artistEntries('Typed Artist'); draft.tracks.find(track => track.slotId === slot)!.title = 'Short title'; });
    const converted = await stored(id), track = v2(converted).tracks.find(value => value.slotId === slot)!;
    assert.deepEqual([converted!.draftVersion, v2(converted).album.artists.map(value => value.name), track.title, saved.item.draft.album.artists.map(value => value.name)], [2, ['Typed Artist'], 'Short title', ['Typed Artist']]);
});

test('the summary state is computed by the server: a public default changed in place, what Publish waits for, Luna ticks, lookup and identity answers, an append, the lookup configuration and the budget left', async () => {
    const by = actor.toHexString(), created = await create(), id = created.item.id;
    assert.equal(created.item.draft.album.visibility, 'public');
    const summary = async () => (await getAdminImportLookup(by, id)).summary;
    // Nothing is named yet, so the new Album and its track are preselected and no identity row needs an answer. Without an
    // operator contact this server cannot run metadata lookup.
    assert.deepEqual(await summary(), { append: false, waiting: { uploads: true, lookup: false, analysis: false }, placeholderOnly: false, luna: [], analysis: { runs: 2, attempts: 22, daily: 220 },
        lookupAvailable: false, identityAnswers: 0 });
    assert.equal((await getAdminImportLookup(by, id, () => ({ available: true, userAgent: 'Synthetic/1.0' }))).summary.lookupAvailable, true);
    // Visibility is changed in place by an ordinary field save, and back.
    const hidden = await editAdminImport(by, id, { ...mutation(1), changes: [{ path: 'album.visibility', base: 'public', value: 'hidden' }] });
    assert.equal(hidden.item.draft.album.visibility, 'hidden');
    const shown = await editAdminImport(by, id, { ...mutation(hidden.item.revision), changes: [{ path: 'album.visibility', base: 'hidden', value: 'public' }] });
    const analyzed = await analyzeAdminImport(by, id, mutation(shown.item.revision), provider);
    assert.equal((await summary()).waiting.analysis, true);
    await settle(provider);
    const done = await getAdminImport(by, id), title = done.item.suggestions.find(value => value.field === 'title')!;
    // The empty title's suggestion arrives ticked; two provider calls are spent from the project and the day.
    assert.deepEqual(await summary(), { append: false, waiting: { uploads: true, lookup: false, analysis: false }, placeholderOnly: false, luna: [{ id: title.id, tick: 'ticked' }], analysis: { runs: 1, attempts: 20, daily: 218 },
        lookupAvailable: false, identityAnswers: 0 });
    assert.equal(analyzed.item.analysis.generation, 1);
    // A ready Album already named like the saved title is a candidate: the Album is no longer preselected, nor is its track.
    await getDb()!.collection('albums').insertOne({ _id: new ObjectId(), title: 'Mine', audioTrackIds: [], visibility: 'public', lifecycleStatus: 'ready' });
    const saved = await editAdminImport(by, id, { ...mutation(done.item.revision), changes: [{ path: 'album.title', base: '', value: 'Mine' }] });
    assert.deepEqual([(await summary()).luna, (await summary()).identityAnswers], [[{ id: title.id, tick: 'conflict' }], 2]);
    // A conflict with the administrator's own title needs an answer until an explicit Album reuse makes the import an append.
    const lookups = getDb()!.collection('adminImportLookups');
    await lookups.insertOne({ _id: new ObjectId(id), run: 1, state: 'complete', issue: null, outcome: 'candidates', input: { trigger: 'submitted', submitted: { kind: 'album', text: 'Mine' } }, candidates: [], ranking: null, staleSlotIds: [],
        applied: { run: 1, candidateKey: `musicbrainz:${'0'.repeat(8)}-0000-4000-8000-${'0'.repeat(12)}`, releaseId: null, choice: 'chosen', basis: 'chosen', values: [], flagged: [],
            conflicts: [{ path: 'album.title', lookup: 'Lookup Title', slotId: null, answer: null }, { path: `tracks.${saved.item.draft.tracks[0].slotId}.title`, lookup: 'Lookup Song', slotId: saved.item.draft.tracks[0].slotId, answer: null }] } } as never);
    // A stored conflict needs an answer while the draft value differs from the lookup value, an empty value included, and
    // still does once the administrator saves another value of their own.
    const track = `tracks.${saved.item.draft.tracks[0].slotId}.title` as const;
    assert.deepEqual((await getAdminImportLookup(by, id)).lookup!.needsAnswer, { tie: false, conflicts: ['album.title', track] });
    const song = await editAdminImport(by, id, { ...mutation(saved.item.revision), changes: [{ path: track, base: '', value: 'My Song' }] });
    assert.deepEqual((await getAdminImportLookup(by, id)).lookup!.needsAnswer, { tie: false, conflicts: ['album.title', track] });
    // A saved Album reuse (an append to an existing Album) applies no Album value, so its title conflict needs no answer.
    await rewrite(id, doc => { doc.decisions = [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId: new ObjectId().toHexString(), candidateRevision: 'f'.repeat(64) } as ImportDecisionV2]; });
    const appended = await getAdminImportLookup(by, id);
    // The target has no member like the file, so its track is preselected as a new member and no identity row needs an answer.
    assert.deepEqual([appended.summary.append, appended.lookup!.needsAnswer.conflicts, appended.summary.identityAnswers], [true, [track], 0]);
    // Saving the lookup's own value answers the track conflict without an explicit answer.
    await editAdminImport(by, id, { ...mutation(song.item.revision), changes: [{ path: track, base: 'My Song', value: 'Lookup Song' }] });
    assert.deepEqual((await getAdminImportLookup(by, id)).lookup!.needsAnswer.conflicts, []);
});
